<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';require_permission('content.manage');$pdo=db();
$fields=['hero_eyebrow'=>'Etiqueta superior','hero_title'=>'Título principal','hero_text'=>'Texto principal','about_title'=>'Título sección nosotros','about_text'=>'Texto sección nosotros'];
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$st=$pdo->prepare('INSERT INTO content_blocks(content_key,label,content_value) VALUES(?,?,?) ON DUPLICATE KEY UPDATE label=VALUES(label),content_value=VALUES(content_value)');foreach($fields as $k=>$label)$st->execute([$k,$label,trim((string)($_POST[$k]??''))]);log_activity('content_update','Updated page content');flash('success','Contenido actualizado correctamente.');header('Location: content.php');exit;}catch(Throwable $e){flash('error',$e->getMessage());}}
$values=[];foreach($pdo->query('SELECT content_key,content_value FROM content_blocks')->fetchAll() as $r)$values[$r['content_key']]=$r['content_value'];$pageTitle='Page Content';$active='content';require __DIR__.'/_header.php';?>
<div class="page-heading"><div><p class="eyebrow">CONTENIDO</p><h1>Portada del sitio</h1><p class="muted">Edita los textos principales sin tocar código.</p></div><a class="button secondary" href="../" target="_blank">↗ Vista previa</a></div><form class="panel form-grid" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><?php foreach($fields as $k=>$label):?><label class="<?=$k==='hero_text'||$k==='about_text'?'full':''?>"><?=h($label)?><?php if(str_contains($k,'text')):?><textarea name="<?=h($k)?>"><?=h($values[$k]??'')?></textarea><?php else:?><input name="<?=h($k)?>" value="<?=h($values[$k]??'')?>"><?php endif;?></label><?php endforeach;?><div class="full form-actions"><button>Guardar cambios</button></div></form><?php require __DIR__.'/_footer.php';?>
